// The annex of the site's PDFs: «Anexo · Condições do patrocínio · versão de 29.10.2026», the full text of the sponsorship
// terms (/condicoes/) after the document's own first page, in the language of the document. The text comes as data
// (terms-text.js, generated by scripts/stamp.mjs from the page, or an older version from data/terms/<date>.json); this
// file only lays it out, with pdf-kit.js, on A4 pages with the first page's margins: a running head, the summary in the
// tinted box, headings that never end a page, paragraphs and list items that may break across pages without leaving a
// line alone, the season discount table never split, links (the live page, Privacidade, email, WhatsApp), and a footer
// with the version, the address of the live page and «Página 2 de 7». receipt.js (the comprovativo) and
// admin-confirm-pdf.js (the confirmation) use it; nothing here is loaded until a PDF is made.
//   annexPages({ lang, doc: 'rcpt' | 'conf', date, terms, url }, first) -> [{ ops, links }]
//   linkOver(ops, text, uri) -> the link annotations over a text already drawn on a page (page 1's terms address)

import { W, H, M, CW, win, width, wrap, INK, MUTED, GOLD_INK, LINE, TINT, rg, emblem, draw } from './pdf-kit.js';

const EN_M = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const dotDate = (d) => String(d).split('-').reverse().join('.');
const enLong = (d) => { const [y, m, n] = String(d).split('-').map(Number); return `${n} ${EN_M[m - 1]} ${y}`; };
// the annex's own words (the page's words come with the text); doc: 'rcpt' the comprovativo of a request, 'conf' the
// confirmation of a sponsorship
const WORDS = {
  pt: {
    kicker: 'Anexo', running: 'Anexo · Condições do patrocínio', outline: 'Anexo · Condições do patrocínio',
    title: (v) => `Condições do patrocínio · versão de ${v}`, ver: dotDate,
    intro: (v, doc, link) => [`O texto completo das condições do patrocínio na versão de ${v}, a que ${doc === 'conf' ? 'este patrocínio' : 'este pedido'} segue. A página `, link, ' mostra sempre a versão mais recente; este anexo guarda esta.'],
    foot: (v) => `Condições do patrocínio · versão de ${v}`, pageOf: (i, t) => `Página ${i} de ${t}`,
  },
  en: {
    kicker: 'Annex', running: 'Annex · Sponsorship terms', outline: 'Annex · Sponsorship terms',
    title: (v) => `Sponsorship terms · version of ${v}`, ver: enLong,
    intro: (v, doc, link) => [`The full text of the sponsorship terms in the version of ${v}, which ${doc === 'conf' ? 'this sponsorship' : 'this request'} follows. The page `, link, ' always shows the latest version; this annex keeps this one.'],
    foot: (v) => `Sponsorship terms · version of ${v}`, pageOf: (i, t) => `Page ${i} of ${t}`,
  },
};
export const annexOutline = (lang) => WORDS[lang === 'en' ? 'en' : 'pt'].outline;

// ---------- rich text: runs -> lines of segments ----------
// runs: 'text' | { b } | { a, href } | { x, to }; size; max width -> [[{ f, s, link }]]. Lines break only at spaces (a
// no-break space keeps «2 000 €» whole); a word longer than the line (a long address) is cut where it has to be.
export function wrapRuns(runs, size, max) {
  const toks = [];
  for (const r of runs) {
    const o = typeof r === 'string' ? { t: r, f: 1 } : r.b != null ? { t: r.b, f: 2 } : r.a != null ? { t: r.a, f: 1, link: r.href } : { t: r.x, f: 1 };
    // each word with the space after it
    for (const w of win(o.t).split(/(?<= )/)) if (w) toks.push({ f: o.f, s: w, link: o.link });
  }
  const lines = [];
  let line = [], lw = 0;
  for (const tk of toks) {
    const ww = width(tk.s.replace(/ $/, ''), tk.f, size);
    if (line.length && lw + ww > max) { lines.push(line); line = []; lw = 0; }
    if (!line.length && ww > max) {
      const parts = wrap(tk.s.replace(/ $/, ''), tk.f, size, max);
      parts.slice(0, -1).forEach((p) => lines.push([{ ...tk, s: p }]));
      line = [{ ...tk, s: parts.at(-1) + (tk.s.endsWith(' ') ? ' ' : '') }]; lw = width(line[0].s, tk.f, size);
      continue;
    }
    line.push(tk); lw += width(tk.s, tk.f, size);
  }
  if (line.length) lines.push(line);
  // neighbours of the same font and link joined; no blank at the end of a line
  return lines.map((l) => l.reduce((a, s) => { const p = a.at(-1); if (p && p.f === s.f && p.link === s.link) p.s += s.s; else a.push({ ...s }); return a; }, []))
    .map((l) => { const z = l.at(-1); z.s = z.s.replace(/ +$/, ''); return l.filter((s) => s.s); });
}

// ---------- the annex ----------
const TOP = H - M - 44, BOTTOM = M + 30;           // the text area under the running head and over the footer
const P = { size: 9.5, lead: 13.2 }, IND = 14;
export function annexPages(a, first = 1) {
  const lg = a.lang === 'en' ? 'en' : 'pt', w = WORDS[lg], v = w.ver(a.date), T = a.terms;
  const pages = [];
  let ops, links, y, d;
  const newPage = () => {
    ops = []; links = []; d = draw(ops, 1); pages.push({ ops, links });
    // the running head: the emblem, GOCARMO, the annex's name
    emblem(ops, M, H - M - 16, 16);
    d.text(M + 22, H - M - 11.5, 'GOCARMO', { f: 2, size: 9, tc: 1 });
    d.text(W - M, H - M - 11.5, win(w.running), { size: 8.5, color: MUTED, right: true });
    d.rule(M, W - M, H - M - 24, 0.6, LINE);
    y = TOP;
  };
  const room = () => y - BOTTOM;
  // lines of segments from the top y (links in the gold ink, underlined, with their annotation)
  const lines = (ls, x, size, lead, color = INK) => {
    ls.forEach((l, i) => {
      const base = y - size * 0.76 - i * lead;
      let xx = x;
      for (const s of l) {
        const sw = width(s.s, s.f, size);
        d.text(xx, base, s.s, { f: s.f, size, color: s.link ? GOLD_INK : color });
        if (s.link) {
          d.rule(xx, xx + sw, base - 1.6, 0.5, GOLD_INK);
          links.push({ rect: [xx, base - size * 0.25, xx + sw, base + size * 0.85], uri: s.link });
        }
        xx += sw;
      }
    });
    y = y - size * 0.76 - (ls.length - 1) * lead - size * 0.3;
  };
  // the list marker: a short gold dash (the site's .offer li::before), on whole points so it renders evenly
  const dash = (x, top, size) => { const yy = Math.round(top - size * 0.42); ops.push(`${rg(GOLD_INK)} ${x} ${yy} 6 1 re f`); };
  // a paragraph or an item that may break across pages, never leaving one line alone at either side
  const flow = (ls, x, size, lead, color, marker) => {
    let i = 0;
    while (i < ls.length) {
      const fit = Math.max(0, Math.floor((room() - size) / lead) + 1);
      let take = Math.min(fit, ls.length - i);
      if (take < ls.length - i && (take < 2 || ls.length - i - take < 2)) take = take >= 3 && ls.length - i - take + 1 >= 2 ? take - 1 : 0;
      if (take <= 0) { newPage(); continue; }
      if (i === 0 && marker) marker(y, size);
      lines(ls.slice(i, i + take), x, size, lead, color);
      i += take;
      if (i < ls.length) newPage();
    }
  };
  // the season discount table: never split (it moves whole, with its header)
  const table = (t, x, tw) => {
    const rowH = 14, fr = t.head.length === 4 ? [0.4, 0.2, 0.2, 0.2] : t.head.map(() => 1 / t.head.length), cols = fr.map((f) => f * tw);
    if (room() < rowH * (t.rows.length + 1) + 6) newPage();
    const cells = (row, fn) => { let cx = x; row.forEach((c, j) => { fn(c, j, j > 0 ? cx + cols[j] : cx, j > 0); cx += cols[j]; }); };
    cells(t.head, (c, j, cx, r) => d.small(cx, y - 9, c, r ? { right: true } : {}));
    y -= 13; d.rule(x, x + tw, y, 0.6, INK);
    for (const row of t.rows) {
      cells(row, (c, j, cx, r) => d.text(cx, y - 10, win(c), { size: 9, right: r }));
      y -= rowH; d.rule(x, x + tw, y, 0.4);
    }
    y -= 4;
  };
  const item = (it, x, iw) => {
    const r = Array.isArray(it) ? it : it.r;
    flow(wrapRuns(r, P.size, iw), x, P.size, P.lead, INK, (top, size) => dash(x - IND + 1, top, size));
    if (!Array.isArray(it) && it.table) { y -= 7; table(it.table, x, Math.min(iw, 330)); }
    y -= 4.5;
  };

  newPage();
  // the annex's own head: what it is, its version, the live page
  d.small(M, y - 7.5, w.kicker, { color: GOLD_INK });
  y -= 13;
  y = d.para(M, y, w.title(v), CW, { f: 2, size: 16, lead: 19.5 }) - 6;
  lines(wrapRuns(w.intro(v, a.doc, { a: 'gocarmo.com/condicoes', href: a.url }), 9.5, CW), M, 9.5, 13.2, MUTED);
  y -= 10;
  d.rule(M, W - M, y, 1, GOLD_INK);
  y -= 16;
  // the page's own title, lead and date
  y = d.para(M, y, T.h1, CW, { f: 2, size: 13, lead: 16 }) - 4;
  y = d.para(M, y, T.lead, CW, { size: 9.5, lead: 13.2, color: MUTED }) - 2;
  y = d.para(M, y, T.updated, CW, { size: 8.5, color: MUTED }) - 12;

  // the lines that follow a heading (up to three): a heading needs room for itself and them
  const after = (j) => {
    const nb = T.blocks[j + 1];
    if (!nb) return 0;
    if (nb.k === 'p') return Math.min(3, wrapRuns(nb.r, P.size, CW).length);
    if (nb.k === 'ul') { const it = nb.items[0]; return Math.min(3, wrapRuns(Array.isArray(it) ? it : it.r, P.size, CW - IND).length); }
    return 3;
  };
  for (const [j, b] of T.blocks.entries()) {
    if (b.k === 'sum') {
      // the summary in the tinted box of the first page; never split (it moves whole to the next page)
      const pad = 11, iw = CW - 2 * pad - IND, ls = b.items.map((it) => wrapRuns(Array.isArray(it) ? it : it.r, P.size, iw));
      const h = 16 + ls.reduce((s, l) => s + P.size * 1.06 + (l.length - 1) * P.lead + 4.5, 0) + 2 * pad - 4;
      if (room() < h) newPage();
      const top = y, at = ops.length;
      y -= pad;
      d.small(M + pad, y - 7.5, b.h);
      y -= 16;
      for (const l of ls) { dash(M + pad + 1, y, P.size); lines(l, M + pad + IND, P.size, P.lead); y -= 4.5; }
      y -= pad - 4;
      const inner = ops.splice(at);
      d.box(M, y, CW, top - y, 6, TINT, GOLD_INK);
      ops.push(...inner);
      y -= 14;
    } else if (b.k === 'h2') {
      // a heading never ends a page: it needs room for itself and the first lines under it (three, or fewer when the
      // text is shorter: «Contacto» and its one line stay on the page they fit)
      const hl = wrap(win(b.t), 2, 11.5, CW).length;
      if (room() < 11.5 + (hl - 1) * 14 + 8 + Math.max(1, after(j)) * P.lead) newPage(); else y -= 6;
      y = d.para(M, y, b.t, CW, { f: 2, size: 11.5, lead: 14 }) - 5;
    } else if (b.k === 'p') {
      flow(wrapRuns(b.r, P.size, CW), M, P.size, P.lead, INK);
      y -= 6;
    } else if (b.k === 'ul') {
      for (const it of b.items) item(it, M + IND, CW - IND);
      y -= 3;
    } else throw new Error(`annex: a block of kind ${b.k}`);
  }
  // the footers, now that the total is known: the version and the live page (a link), the page number
  const total = first + pages.length;
  pages.forEach((pg, i) => {
    const dd = draw(pg.ops, 1), left = `${win(w.foot(v))} · `, lw = width(left, 1, 8), u = 'gocarmo.com/condicoes';
    dd.rule(M, W - M, M + 14, 0.5, LINE);
    dd.text(M, M + 3, left, { size: 8, color: MUTED });
    dd.text(M + lw, M + 3, u, { size: 8, color: GOLD_INK });
    pg.links.push({ rect: [M + lw, M + 1, M + lw + width(u, 1, 8), M + 11], uri: a.url });
    dd.text(W - M, M + 3, win(w.pageOf(first + i + 1, total)), { size: 8, color: MUTED, right: true });
    if (dd.over()) throw new Error('annex: a footer ran past the margins');
  });
  return pages;
}

// The link annotations over a text a page already drew (one text operator per line, as pdf-kit's draw() writes them),
// so a page that is not to change by a byte still gets its address as a link
const unlit = (s) => s.replace(/\\([0-7]{3}|[\\()])/g, (m, c) => (c.length === 3 ? String.fromCharCode(parseInt(c, 8)) : c));
export function linkOver(ops, text, uri) {
  const key = win(text), out = [];
  for (const op of ops) {
    const m = /^BT \/F(\d) ([\d.]+) Tf ([\d.-]+) Tc .* 1 0 0 1 ([\d.-]+) ([\d.-]+) Tm \((.*)\) Tj ET$/.exec(op);
    if (!m) continue;
    const [, f, size, tc, x, y, body] = m, s = unlit(body), k = s.indexOf(key);
    if (k < 0) continue;
    const x0 = Number(x) + width(s.slice(0, k), Number(f), Number(size), Number(tc)), z = Number(size);
    out.push({ rect: [x0, Number(y) - z * 0.25, x0 + width(key, Number(f), z, Number(tc)), Number(y) + z * 0.85], uri });
  }
  return out;
}
